$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force
Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force
Import-Module (Join-Path $PSScriptRoot 'Repato.Deployment.psm1') -Force
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$passed=0
function Check([bool]$ok,[string]$name){if(!$ok){throw "FAILED: $name"};$script:passed++}
function Reject([scriptblock]$x,[string]$name){$ok=$false;try{&$x|Out-Null}catch{$ok=$true};Check $ok $name}
function New-Case {
 param([string]$Store,[string]$Worktree,[string]$Candidate,[string]$Commit,[object]$DeploymentEvidence)
 New-Item $Candidate -ItemType Directory -Force|Out-Null
 & git -C $root worktree add --detach $Worktree $Commit|Out-Null
 $dll=Join-Path $Candidate 'Repato.Revit.dll';$addin=Join-Path $Candidate 'Repato.addin';[IO.File]::WriteAllText($dll,'single canonical synthetic artifact');Set-Content $addin '<RevitAddIns></RevitAddIns>'
 $hash=(Get-FileHash $dll).Hash;$mh=(Get-FileHash $addin).Hash;@{CandidateType='SyntheticReleaseCandidate';SourceCommit=$Commit;FrozenArtifactSha256=$hash;ManifestSha256=$mh;SupportedQaWorkflows=@('create-plan-views-v1')}|ConvertTo-Json|Set-Content (Join-Path $Candidate 'release-manifest.json')
 $source=[pscustomobject]@{RepositoryRoot=$Worktree;ExpectedSourceCommit=$Commit;ProjectRelativePath='Forma.RevitConnector.csproj'}
 $b=New-MayaQaBootstrap -StoreRoot $Store -QaWorkflowId create-plan-views-v1 -RunId ('run-'+[guid]::NewGuid().ToString('N'))
 $null=New-MayaQaBuildRequest -StoreRoot $Store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -UserRequest 'Create Plan Views' -SourceBranch current -ProjectPath 'Forma.RevitConnector.csproj' -AuthenticatedBuildSource $source
 $runner={param($project,$buildRoot) $out=Join-Path $buildRoot 'bin\Release\net8.0-windows';New-Item $out -ItemType Directory -Force|Out-Null;Copy-Item $dll (Join-Path $out 'Repato.Revit.dll');Set-Content (Join-Path $buildRoot 'Repato.addin') '<RevitAddIns></RevitAddIns>';[pscustomobject]@{Lines=@('synthetic build');ExitCode=0}}.GetNewClosure()
 $null=& (Get-Module Repato.MayaQaWorkflow) {param($s,$t,$w,$c,$d,$h,$commit) Bind-MayaQaFrozenCandidateBuildEvidence -StoreRoot $s -TaskId $t -WorkflowId $w -QaWorkflowId create-plan-views-v1 -CandidateDirectory $c -CandidateDllPath $d -ExpectedSha256 $h -ExpectedSourceCommit $commit} $Store $b.TaskId $b.WorkflowId $Candidate $dll $hash $Commit
 $null=& (Get-Module Repato.MayaQaWorkflow) {param($s,$t,$w) Resolve-MayaQaSourceRunnerManifestEvidence -StoreRoot $s -TaskId $t -WorkflowId $w -QaWorkflowId create-plan-views-v1 -TestId create-plan-views-v1} $Store $b.TaskId $b.WorkflowId
 $null=Invoke-MayaQaFrozenCandidateEvidence -StoreRoot $Store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -CandidateDirectory $Candidate -ExpectedSha256 $hash -ExpectedSourceCommit $Commit -DeploymentEvidence $DeploymentEvidence
 [pscustomobject]@{Bootstrap=$b;Hash=$hash;CandidateHash=(Get-FileHash $dll).Hash}
}
$beforeRuns=@(Get-ChildItem (Join-Path $root 'QA\TestRuns') -Force -ErrorAction SilentlyContinue|% FullName);$fixture=Join-Path $root 'QA\Fixtures\CreatePlanViewsEmpty.rvt';$fixtureHash=(Get-FileHash $fixture).Hash
$runnerPath='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\Repato.CreatePlanViews.TestRunner.addin';$runnerHash='AF4DBFA78E61524DE7BD3B84178C6B70ED8D29D0A95BA17780826E09BE689D4F';$valid=[pscustomobject]@{succeeded=$true;runnerManifestPath=$runnerPath;runnerManifestSha256=$runnerHash;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA';isolationPassed=$true;manifestIntegrityEvidenceAvailable=$true;manifestIntegrityPassed=$true}
$store=Join-Path ([IO.Path]::GetTempPath()) ('maya-single-attempt-'+[guid]::NewGuid().ToString('N'));$worktree=Join-Path 'C:\Repato-Autonomous\Worktrees' ('test-'+[guid]::NewGuid().ToString('N'));$candidate=Join-Path (Join-Path $root 'DeploymentCandidates\AgentBuilds') ('SingleCanonicalAttempt-'+[guid]::NewGuid().ToString('N'));$negativeStores=[Collections.Generic.List[string]]::new();$negativeCandidates=[Collections.Generic.List[string]]::new();$negativeCandidates.Add($candidate)|Out-Null;$commit=(& git -C $root rev-parse HEAD).Trim();$candidateHash=$null
try {
 $case=New-Case $store $worktree $candidate $commit $valid;$candidateHash=$case.CandidateHash;$b=$case.Bootstrap
 $d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $b.TaskId;$w=@($t.deploymentWorkflows|Where-Object workflowId -eq $b.WorkflowId)[0]
 Check ($w.qaBuildEvidence.SourceCommit -ceq $commit) 'source-bound Neil evidence persisted';Check (![string]::IsNullOrWhiteSpace([string]$w.qaBuildEvidence.RunnerManifestPath)) 'runner manifest path persisted';Check ($w.qaBuildEvidence.RunnerManifestSha256 -eq $runnerHash) 'runner manifest hash persisted';Check ($w.qaBuildEvidence.DeploymentValidation) 'deployment validation persisted';Check ($w.qaBuildEvidence.ManifestIntegrityValidation) 'manifest integrity persisted';Check ($w.qaBuildEvidence.QaIsolation) 'isolation persisted'
 $prepRoot=Join-Path $root ('QA\TestRuns\single-prep-'+[guid]::NewGuid().ToString('N'));New-Item $prepRoot -ItemType Directory|Out-Null;$prepAttempt=[guid]::NewGuid().ToString('N');$prepRun=[guid]::NewGuid().ToString('N');$prepModel=Join-Path $prepRoot 'model.rvt';Copy-Item $fixture $prepModel;$prepRequest=Join-Path $prepRoot ($prepAttempt+'.request.json');$prepResult=$prepRequest+'.preparation.json';[ordered]@{operation='prepare-disposable-create-plan-views-fixture';taskId=$b.TaskId;workflowId=$b.WorkflowId;attemptId=$prepAttempt;runId=$prepRun;requestPath=$prepRequest;modelPath=$prepModel;modelSha256=$fixtureHash;outputPath=$prepResult}|ConvertTo-Json|Set-Content $prepRequest;[ordered]@{Status='Passed';Operation='prepare-disposable-create-plan-views-fixture';TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;AttemptId=$prepAttempt;RunId=$prepRun;ModelPath=$prepModel;SourceModelSha256=$fixtureHash;PreparedModelSha256=$fixtureHash}|ConvertTo-Json|Set-Content $prepResult
 Invoke-RepatoStoreMutation $store {param($d,$p)$x=Find-RepatoTask $d $b.TaskId;$x.status='in-progress';$x.workflowStage='build-checks';$x.approvalRequests=[object[]]@();$x}|Out-Null
 Invoke-RepatoStoreMutation $store {param($d,$p)$x=Find-RepatoTask $d $b.TaskId;@($x.deploymentWorkflows|Where-Object workflowId -ceq $b.WorkflowId)[0].qaRunId=$null;$x}|Out-Null
 $run=New-MayaQaRun -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -RunId $b.RunId -FixturePreparationResultPath $prepResult;$ww=Get-DeployWorkflow $store $b.TaskId $b.WorkflowId;$tt=Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId;Update-RepatoTask $store $b.TaskId in-progress qa Maya $null $null -ExpectedTaskRevision $tt.revision -ExpectedWorkflowId $b.WorkflowId -ExpectedWorkflowRevision $ww.workflowRevision -ExpectedQaWorkflowId create-plan-views-v1|Out-Null;Update-RepatoTask $store $b.TaskId passed qa Tara $null $null|Out-Null;Request-RepatoTaskApproval $store $b.TaskId qa-run maya|Out-Null;Resolve-RepatoTaskApproval $store $b.TaskId approve Maya synthetic|Out-Null;$prep=New-MayaQaCanonicalPreparation -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1;$t=Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId
 Check ($prep.Attempt.AttemptId -eq $t.mayaTaraAttempt.AttemptId) 'approval-to-handoff attempt linkage';Check (@($t.mayaTaraAttempt).Count -eq 1) 'exactly one canonical attempt';Check ($prep.Handoff.RunnerManifestPath -eq $w.qaBuildEvidence.RunnerManifestPath) 'handoff runner manifest path';Check ($prep.Handoff.RunnerManifestSha256 -eq $runnerHash) 'handoff runner manifest hash';Check ($t.mayaTaraAttempt.QaWorkflowId -eq 'create-plan-views-v1') 'persisted QA workflow identity';Reject {New-MayaQaCanonicalPreparation -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1} 'duplicate canonical attempt rejected'
 $negative=@([pscustomobject]@{Name='missing';Evidence=[pscustomobject]@{succeeded=$true;isolationPassed=$true}};[pscustomobject]@{Name='wrong-path';Evidence=[pscustomobject]@{succeeded=$true;runnerManifestPath='C:\wrong.addin';runnerManifestSha256=$runnerHash;qaAddinRoot=$valid.qaAddinRoot;isolationPassed=$true;manifestIntegrityEvidenceAvailable=$true;manifestIntegrityPassed=$true}};[pscustomobject]@{Name='wrong-hash';Evidence=[pscustomobject]@{succeeded=$true;runnerManifestPath=$runnerPath;runnerManifestSha256=('0'*64);qaAddinRoot=$valid.qaAddinRoot;isolationPassed=$true;manifestIntegrityEvidenceAvailable=$true;manifestIntegrityPassed=$true}};[pscustomobject]@{Name='validation-failure';Evidence=[pscustomobject]@{succeeded=$false;errorCode='synthetic-validation-failure'}})
 foreach($n in $negative){$s=Join-Path ([IO.Path]::GetTempPath()) ('maya-single-negative-'+[guid]::NewGuid().ToString('N'));$negativeStores.Add($s)|Out-Null;$wt=Join-Path 'C:\Repato-Autonomous\Worktrees' ('test-'+[guid]::NewGuid().ToString('N'));$c=Join-Path (Join-Path $root 'DeploymentCandidates\AgentBuilds') ('SingleCanonicalAttempt-'+[guid]::NewGuid().ToString('N'));$negativeCandidates.Add($c)|Out-Null;try{$x=New-Case $s $wt $c $commit $valid;Reject {Invoke-MayaQaFrozenCandidateEvidence -StoreRoot $s -TaskId $x.Bootstrap.TaskId -WorkflowId $x.Bootstrap.WorkflowId -QaWorkflowId create-plan-views-v1 -CandidateDirectory $c -ExpectedSha256 $x.Hash -ExpectedSourceCommit $commit -DeploymentEvidence $n.Evidence} "$($n.Name) validation rejected";$nt=Find-RepatoTask (Read-RepatoTaskStore $s) $x.Bootstrap.TaskId;Check (-not ($nt.PSObject.Properties.Name -contains 'mayaTaraAttempt')) "$($n.Name) no Tara attempt";Check (-not ($nt.PSObject.Properties.Name -contains 'mayaTaraExecution')) "$($n.Name) no native claim"}finally{if(Test-Path $wt){& git -C $root worktree remove --force $wt 2>$null|Out-Null};Remove-Item $s -Recurse -Force -ErrorAction SilentlyContinue; if(Test-Path -LiteralPath $c){Remove-Item -LiteralPath $c -Recurse -Force -ErrorAction SilentlyContinue}}}
 Check ((Get-FileHash $fixture).Hash -ceq $fixtureHash) 'fixture immutable';Check ((Get-FileHash (Join-Path $candidate 'Repato.Revit.dll')).Hash -ceq $candidateHash) 'candidate immutable';$afterRuns=@(Get-ChildItem (Join-Path $root 'QA\TestRuns') -Force -ErrorAction SilentlyContinue|% FullName);$newRuns=@($afterRuns|Where-Object{$beforeRuns -notcontains $_});foreach($r in $newRuns){Remove-Item $r -Recurse -Force -ErrorAction SilentlyContinue};$afterRuns=@(Get-ChildItem (Join-Path $root 'QA\TestRuns') -Force -ErrorAction SilentlyContinue|% FullName);Check ((Compare-Object $beforeRuns $afterRuns).Count -eq 0) 'QA TestRuns inventory stable';[pscustomobject]@{Status='PASS';AssertionsPassed=$passed;AssertionsFailed=0;AttemptCount=1;NativeRequestCount=0;RevitLaunched=$false}|ConvertTo-Json -Compress
}finally{if(Test-Path $worktree){& git -C $root worktree remove --force $worktree 2>$null|Out-Null};Remove-Item $store -Recurse -Force -ErrorAction SilentlyContinue;foreach($s in $negativeStores){Remove-Item $s -Recurse -Force -ErrorAction SilentlyContinue};foreach($c in $negativeCandidates){if(Test-Path -LiteralPath $c){Remove-Item -LiteralPath $c -Recurse -Force -ErrorAction SilentlyContinue}}}
